from pathlib import Path
import re
p=Path('index.html')
s=p.read_text()
new=r'''function draw(){t+=.008;const p=current,w=W,h=H,cx=w*.64,cy=h*.5;ctx.clearRect(0,0,w,h);ctx.fillStyle='#0c0f0c';ctx.fillRect(0,0,w,h);const grd=ctx.createRadialGradient(cx,cy,0,cx,cy,w*.7);grd.addColorStop(0,'#1b2821');grd.addColorStop(.5,'#101711');grd.addColorStop(1,'#0c0f0c');ctx.fillStyle=grd;ctx.fillRect(0,0,w,h);const q=p*5,idx=Math.min(5,Math.floor(q)),local=q-idx,fade=ease(Math.min(1,local));ctx.save();ctx.translate(mouse.x*w*.025,mouse.y*h*.02);
const docX=cx+w*.02,docY=cy-h*.01;
if(idx===0){paper(docX+w*.10*(1-fade),docY,w*.27,h*.48,-.035,1,0,false);paper(docX-w*.17,docY+h*.06,w*.21,h*.37,.08,.72,0,false)}
if(idx===1){paper(docX,docY,w*.27,h*.48,-.02,1,1,false);ctx.strokeStyle='#b8d2c280';ctx.lineWidth=1*dpr;for(let i=0;i<5;i++){const yy=docY-h*.14+i*h*.065;ctx.beginPath();ctx.moveTo(docX+w*.19,yy);ctx.lineTo(docX+w*.31+Math.sin(t+i)*w*.018,yy);ctx.stroke()}for(let i=0;i<4;i++){ctx.fillStyle='#b8d2c2';ctx.globalAlpha=.45+.4*Math.sin(t*2+i);ctx.fillRect(docX+w*.27,docY-h*.14+i*h*.065,4*dpr,4*dpr)}}
if(idx===2){paper(docX,docY,w*.27,h*.48,-.015,1,2,false);ctx.strokeStyle='#b8d2c260';ctx.lineWidth=1*dpr;ctx.strokeRect(docX-w*.085,docY-h*.19,w*.17,h*.38);ctx.fillStyle='#66786d';for(let i=0;i<4;i++)ctx.fillRect(docX-w*.06,docY-h*.13+i*h*.07,w*.12,2*dpr);ctx.fillStyle='#b8d2c2';ctx.fillRect(docX+w*.055,docY+h*.075,w*.045,5*dpr)}
if(idx===3){paper(docX-w*.16,docY,w*.24,h*.43,.055,1,3,false);paper(docX+w*.16,docY,w*.24,h*.43,-.055,1,3,true);ctx.strokeStyle='#d49b91aa';ctx.lineWidth=1*dpr;ctx.beginPath();ctx.moveTo(docX-w*.025,docY-h*.10);ctx.lineTo(docX+w*.025,docY-h*.10);ctx.stroke();ctx.beginPath();ctx.moveTo(docX-w*.025,docY+h*.015);ctx.lineTo(docX+w*.025,docY+h*.015);ctx.stroke();ctx.fillStyle='#d49b91';ctx.beginPath();ctx.arc(docX,docY+h*.11,4*dpr,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.55+.35*Math.sin(t*2);ctx.strokeStyle='#d49b9180';ctx.beginPath();ctx.arc(docX,docY+h*.11,10*dpr,0,Math.PI*2);ctx.stroke()}
if(idx===4){paper(docX,docY,w*.28,h*.49,-.01,1,4,false);ctx.strokeStyle='#b8d2c280';ctx.lineWidth=1*dpr;ctx.strokeRect(docX-w*.105,docY-h*.205,w*.21,h*.41);for(let i=0;i<3;i++){const yy=docY-h*.11+i*h*.085;ctx.strokeStyle=i===1?'#d49b91aa':'#b8d2c260';ctx.beginPath();ctx.moveTo(docX-w*.075,yy);ctx.lineTo(docX+w*.075,yy);ctx.stroke()}ctx.fillStyle='#b8d2c2';ctx.beginPath();ctx.arc(docX+w*.09,docY+h*.14,5*dpr,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#b8d2c260';ctx.beginPath();ctx.arc(docX+w*.09,docY+h*.14,12*dpr,0,Math.PI*2);ctx.stroke()}
if(idx===5){paper(docX,docY,w*.31,h*.53,-.008,1,5,false);ctx.strokeStyle='#b8d2c275';ctx.lineWidth=1*dpr;ctx.strokeRect(docX-w*.125,docY-h*.22,w*.25,h*.44);ctx.fillStyle='#b8d2c2';ctx.fillRect(docX+w*.075,docY-h*.19,7*dpr,7*dpr);ctx.strokeStyle='#b8d2c270';ctx.beginPath();ctx.moveTo(docX-w*.085,docY+h*.12);ctx.lineTo(docX-w*.015,docY+h*.17);ctx.lineTo(docX+w*.10,docY+h*.02);ctx.stroke();ctx.globalAlpha=.18+.12*Math.sin(t*1.5);ctx.strokeStyle='#b8d2c2';ctx.beginPath();ctx.arc(docX,docY,Math.min(w,h)*.25,0,Math.PI*2);ctx.stroke()}
ctx.restore();const scanY=h*(.22+.56*((t+p*1.6)%1));ctx.fillStyle='#b8d2c212';ctx.fillRect(0,scanY,w,1*dpr);if(p>.12&&p<.9){ctx.fillStyle='#b8d2c208';ctx.fillRect(cx-w*.24,cy-h*.29,w*.48,h*.58)}requestAnimationFrame(draw)}'''
pattern=r'function draw\(\)\{.*?requestAnimationFrame\(draw\)\}'
s2,n=re.subn(pattern,new,s,count=1,flags=re.S)
if n!=1: raise SystemExit('draw function not found')
p.write_text(s2)
